namespace ghidra.pty.windows;







using ghidra.util;

// TODO: I shouldn't have to do any of this.
public class AnsiBufferedInputStream : InputStream {
	private static readonly Charset WINDOWS_1252 = Charset.forName("windows-1252");

	private class Mode
{	public static readonly Mode CHARS = new();
	public static readonly Mode ESC = new();
	public static readonly Mode CSI = new();
	public static readonly Mode CSI_p = new();
	public static readonly Mode CSI_Q = new();
	public static readonly Mode OSC = new();
	public static readonly Mode WINDOW_TITLE = new();
	public static readonly Mode WINDOW_TITLE_ESC = new();

	}

	private InputStream @in;

	private int countIn = 0;

	private ByteBuffer lineBaked = ByteBuffer.allocate(short.MaxValue);
	private ByteBuffer lineBuf = ByteBuffer.allocate(short.MaxValue);
	private ByteBuffer escBuf = ByteBuffer.allocate(1024);
	private ByteBuffer titleBuf = ByteBuffer.allocate(255);

	private Mode mode = Mode.CHARS;

	private int savePosition;  // For ESC 7/8

	public AnsiBufferedInputStream(InputStream @in) {
		if (in is HandleInputStream) {
			// Spare myself the 1-by-1 native calls
			@in= new BufferedInputStream(@in);
		}
		this.@in = in;

		lineBuf.limit(0);
		lineBaked.limit(0);
	}

	/* @Override */
	public int read()
    {
		if (lineBaked.hasRemaining()) {
			return lineBaked.get();
		}
		if (readUntilBaked() < 0) {
			return -1;
		}
		if (lineBaked.hasRemaining()) {
			return lineBaked.get();
		}
		return -1; // EOF
	}

	/* @Override */
	public int read(byte[] b, int off, int len)
    {
		if (!lineBaked.hasRemaining()) {
			if (readUntilBaked() < 0) {
				return -1;
			}
		}
		int read = Math.min(lineBaked.remaining(), len);
		lineBaked.get(b, off, read);
		return read;
	}

	/* @Override */
	public void close()
    {
		@in.close();
		base.close();
	}

	protected int readUntilBaked()
    {
		while (!lineBaked.hasRemaining()) {
			if (processNext() < 0) {
				break;
			}
		}
		if (!lineBaked.hasRemaining()) {
			return -1;
		}
		return lineBaked.remaining();
	}

	protected void printDebugChar(byte c) {
		if (0x20 <= c && c <= 0x7f) {
			Console.Error.Write(new string(new byte[] { c }));
		}
		else {
			Console.Error.Write(string.format("<%02x>", c & 0xff));
		}
	}

	protected int processNext()
    {
		int ci = @in.read();
		if (ci == -1) {
			return -1;
		}
		byte c = (byte) ci;
		//printDebugChar(c);
		switch (mode) {
			case CHARS: return processChars(c);
			case ESC: return processEsc(c);
			case CSI: return processCsi(c);
			case CSI_p: return processCsiParamOrCommand(c);
			case CSI_Q: return processCsiQ(c);
			case OSC: return processOsc(c);
			case WINDOW_TITLE: return processWindowTitle(c);
			case WINDOW_TITLE_ESC: return processWindowTitleEsc(c);
			default: throw new AssertionError();
		}
		countIn++;
		// Don't return a potentially negative number
		return ci;
	}

	/**
	 * There's not really a good way to know if any trailing space was intentional. For GDB/MI, that
	 * doesn't really matter.
	 */
	protected int guessEnd() {
		for (int i = lineBuf.limit() - 1; i >= 0; i--) {
			byte c = lineBuf.get(i);
			if (c != 0x20 && c != 0) {
				return i + 1;
			}
		}
		return 0;
	}

	protected void bakeLine() {
		lineBuf.position(0);
		lineBuf.limit(guessEnd() + 1);
		lineBuf.put(lineBuf.limit() - 1, (byte) '\n');
		ByteBuffer temp = lineBaked;
		lineBaked = lineBuf;
		lineBuf = temp;
		lineBuf.clear();
		Arrays.fill(lineBuf.array(), (byte) 0);
		lineBuf.limit(0);
	}

	protected void appendChar(byte c) {
		int limit = lineBuf.limit();
		if (lineBuf.position() == limit) {
			lineBuf.limit(limit + 1);
		}
		lineBuf.put(c);
	}

	protected void processChars(byte c) {
		switch (c) {
			default: appendChar(c);
			case '\b': {
				if (lineBuf.get(lineBuf.position() - 1) == ' ') {
					lineBuf.position(lineBuf.position() - 1);
				}
			}
			case '\n': return bakeLine();
			case '\r': return lineBuf.position(0);
			case 0x1b: return mode = Mode.ESC;
		}
	}

	protected void processEsc(byte c) {
		switch (c) {
			case '[': return mode = Mode.CSI;
			case ']': return mode = Mode.OSC;
			// At some point, these may be replaced with the more current ESC[s and ESC[u
			case '7': {
				savePosition = lineBuf.position();
				mode = Mode.CHARS;
			}
			case '8': {
				// Check limits
				int pos = Math.min(savePosition, lineBuf.limit());
				lineBuf.position(pos);
				mode = Mode.CHARS;
			}
			default: {
				//mode = Mode.CHARS;
				Msg.debug(this, "Saw 'ESC " + c + "' at " + countIn + " pos=" + lineBuf.position());
			}
		}
	}

	protected void processCsi(byte c) {
		switch (c) {
			default: processCsiParamOrCommand(c);
			case '?': return mode = Mode.CSI_Q;
		}
	}

	protected void processCsiParamOrCommand(byte c) {
		switch (c) {
			default: {
				if ((c >= 0x30 && c <= 0x39) || c == (byte) ';') {
					escBuf.put(c);
				}
				else {
					Msg.debug(this, "Unexpected esc buffer entry: " + c);
				}
			}
			case 'A': {
				execCursorUp();
				mode = Mode.CHARS;
			}
			case 'B': {
				execCursorDown();
				mode = Mode.CHARS;
			}
			case 'C': {
				execCursorForward();
				mode = Mode.CHARS;
			}
			case 'D': {
				execCursorBackward();
				mode = Mode.CHARS;
			}
			case 'G': {
				execCursorCharAbsolute();
				mode = Mode.CHARS;
			}
			case 'H': {
				execCursorPosition();
				mode = Mode.CHARS;
			}
			case 'J': {
				execEraseInDisplay();
				mode = Mode.CHARS;
			}
			case 'K': {
				execEraseInLine();
				mode = Mode.CHARS;
			}
			case 'X': {
				execEraseCharacter();
				mode = Mode.CHARS;
			}
			case 'm': {
				execSetGraphicsRendition();
				mode = Mode.CHARS;
			}
			case 'h': {
				execPrivateSequence(true);
				mode = Mode.CHARS;
			}
			case 'l': {
				execPrivateSequence(false);
				mode = Mode.CHARS;
			}
			case 'f': {
				// Need to flush escBuf at a minimum
				readAndClearEscBuf();
				Msg.debug(this, "TODO: f (Horizontal and Vertical Position - HVP)");
				mode = Mode.CHARS;
			}
			case 'r': {
				// Need to flush escBuf at a minimum
				readAndClearEscBuf();
				Msg.debug(this, "TODO: r (Set Top and Bottom Margins - DECSTBM)");
				mode = Mode.CHARS;
			}
		}
	}

	public static readonly string PRIV_12 = "12";
	public static readonly string PRIV_25 = "25";
	public static readonly string PRIV_1004 = "1004";
	public static readonly string PRIV_2004 = "2004";
	public static readonly string PRIV_9001 = "9001";

	protected void processCsiQ(byte c) {
		switch (c) {
			default: escBuf.put(c);
			case 'h': {
				switch (readAndClearEscBuf()) {
					case PRIV_12: return execTextCursorEnableBlinking();
					case PRIV_25: return execTextCursorEnableModeShow();
					case PRIV_1004: return execEnableFocusReport();
					case PRIV_2004: return execEnableBracketedPasteMode();
					case PRIV_9001: return execEnableWin32InputMode();
					case string buf: return throw new AssertionError("Got CsiQ(h): %s".formatted(buf));
				}
				mode = Mode.CHARS;
			}
			case 'l': {
				switch (readAndClearEscBuf()) {
					case PRIV_12: return execTextCursorDisableBlinking();
					case PRIV_25: return execTextCursorDisableModeShow();
					case PRIV_1004: return execDisableFocusReport();
					case PRIV_2004: return execDisableBracketedPasteMode();
					case PRIV_9001: return execDisableWin32InputMode();
					case string buf: return throw new AssertionError("Got CsiQ(l): %s".formatted(buf));
				}
				mode = Mode.CHARS;
			}
		}
	}

	protected void processOsc(byte c) {
		switch (c) {
			default: escBuf.put(c);
			case ';': {
				switch (readAndClearEscBuf()) {
					case "0", "2": return mode = Mode.WINDOW_TITLE;
					default: throw new AssertionError();
				}
			}
		}
	}

	protected void processWindowTitle(byte c) {
		switch (c) {
			default: titleBuf.put(c);
			case 0x07: { // bell, even though MSDN says longer form preferred
				execSetWindowTitle();
				mode = Mode.CHARS;
			}
			case 0x1b: return mode = Mode.WINDOW_TITLE_ESC;
		}
	}

	protected void processWindowTitleEsc(byte c) {
		switch (c) {
			case '\\': {
				execSetWindowTitle();
				mode = Mode.CHARS;
			}
			default: throw new AssertionError("Saw <ST> ... ESC " + c + " at " + countIn);
		}
	}

	protected string readAndClear(ByteBuffer buf) {
		buf.flip();
		string result = new string(buf.array(), buf.position(), buf.remaining(), WINDOWS_1252);
		buf.clear();
		return result;
	}

	protected string readAndClearEscBuf() {
		return readAndClear(escBuf);
	}

	protected int parseNumericBuffer() {
		string numeric = readAndClearEscBuf();
		if (numeric.isEmpty()) {
			return 0;
		}
		int result = Integer.parseInt(numeric);
		return result;
	}

	protected int[] parseNumericListBuffer() {
		string numericList = readAndClearEscBuf();
		if (numericList.isEmpty()) {
			return new int[] {};
		}
		return Stream.of(numericList.split(";"))
				.mapToInt(Integer.parseInt)
				.toArray();
	}

	protected void execCursorUp() {
		readAndClearEscBuf();
		//throw new UnsupportedOperationException("Cursor Up");
	}

	protected void execCursorDown() {
		readAndClearEscBuf();
		//throw new UnsupportedOperationException("Cursor Down");
	}

	protected void setPosition(int newPosition) {
		if (lineBuf.limit() < newPosition) {
			lineBuf.limit(newPosition);
		}
		lineBuf.position(newPosition);
	}

	protected void execCursorForward() {
		int delta = parseNumericBuffer();
		setPosition(lineBuf.position() + delta);
	}

	protected void execCursorBackward() {
		int delta = parseNumericBuffer();
		lineBuf.position(lineBuf.position() - delta);
	}

	protected void execCursorCharAbsolute() {
		int[] abset = parseNumericListBuffer();
		int abs = Math.min(abset[0] - 1, lineBuf.limit());
		lineBuf.position(abs);
	}

	protected void execCursorPosition() {
		int[] yx = parseNumericListBuffer();
		if (yx.length == 0) {
			lineBuf.position(0);
			return;
		}
		if (yx.length != 2) {
			throw new AssertionError();
		}
		if (yx[0] != 1) {
			Msg.warn(this, "ANSI: CursorPosition y != 1 (%d)".formatted(yx[0]));
		}
		setPosition(yx[1] - 1);
	}

	protected void execTextCursorEnableBlinking() {
		// Don't care
	}

	protected void execTextCursorDisableBlinking() {
		// Don't care
	}

	protected void execTextCursorEnableModeShow() {
		// Don't care
	}

	protected void execTextCursorDisableModeShow() {
		// Don't care
	}

	protected void execEnableFocusReport() {
		// Don't care
	}

	protected void execDisableFocusReport() {
		// Don't care
	}

	protected void execEnableBracketedPasteMode() {
		// Don't care
	}

	protected void execDisableBracketedPasteMode() {
		// Don't care
	}

	protected void execEnableWin32InputMode() {
		// Don't care
	}

	protected void execDisableWin32InputMode() {
		// Don't care
	}

	protected void execEraseInDisplay() {
		// Because I have only one line, right?
		execEraseInLine();
	}

	protected void execEraseInLine() {
		int[] abset = parseNumericListBuffer();
		int abs = abset.length == 0 ? 0 : abset[0];
		switch (abs) {
			case 0 => Arrays.fill(lineBuf.array(), lineBuf.position(), lineBuf.capacity(),
				(byte) 0);
			case 1: return Arrays.fill(lineBuf.array(), 0, lineBuf.position() + 1, (byte) 0);
			case 2: return Arrays.fill(lineBuf.array(), (byte) 0);
		}
	}

	protected void execEraseCharacter() {
		int count = parseNumericBuffer();
		Arrays.fill(lineBuf.array(), lineBuf.position(), lineBuf.position() + count, (byte) ' ');
	}

	protected void execSetGraphicsRendition() {
		// TODO: Maybe echo these or provide callbacks
		// Otherwise, don't care
		escBuf.clear();
	}

	protected void execSetWindowTitle() {
		// Msg.info(this, "Title: " + readAndClear(titleBuf));
		// TODO: Maybe a callback. Otherwise, don't care
		titleBuf.clear();
	}

	protected void execPrivateSequence(bool enable) {
		// These don't matter for input buffering.
		escBuf.clear();
	}
}
